import{_ as a,o as t,c as o,a5 as s}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Transportes atuais e restrições de plataforma","description":"","frontmatter":{"title":"Transportes atuais e restrições de plataforma","docId":"developer.transports","translationKey":"developer.transports","locale":"pt","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6696987a0db16b3b4d364c6136d0e552dbebd6fc68346e3ed031587a7b004468","translationRevision":"44cc2292048adab16facd7f68c88ad9dcab44f4eefdc6db2a0c8e60a1745aa1a","order":200},"headers":[],"relativePath":"pt/developer/transports.md","filePath":"pt/developer/transports.md","lastUpdated":1794611623000}'),r={name:"pt/developer/transports.md"};function i(d,e,n,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Transportes atuais e restrições de plataforma <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;Transportes atuais e restrições de plataforma {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Selecione o transporte que realmente existe para a compilação e plataforma de destino. Leia <a href="./control-api.html">API de controle</a> e <a href="./collaboration.html">colaboração</a>. Um transporte carrega operações serializadas; ele não deve introduzir um segundo núcleo nem conceder autoridade por si só.</p><h2 id="choose-the-boundary" tabindex="-1">Escolha o limite <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;Escolha o limite {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Caminho</th><th>Implementação atual</th><th>Limite importante</th></tr></thead><tbody><tr><td>WebView de desktop</td><td>IPC do Wry e cliente de controle compartilhado</td><td>O tempo de vida da GUI/thread pertence ao desktop</td></tr><tr><td>CLI local</td><td>Socket Unix ou pipe nomeado Windows; host stdio explícito</td><td>Mesmo diretório de dados e proprietário do aplicativo</td></tr><tr><td>Navegador local</td><td>Adaptador nativo de loopback mais <code>browser-transport.ts</code></td><td>Host nativo pareado, não uma simulação ou servidor remoto público</td></tr><tr><td>Remoto direto</td><td>Gateway HTTPS/WSS autenticado e transportes SDK/navegador</td><td>TLS, hello, concessões e controles de recursos</td></tr><tr><td>Par nativo</td><td><code>tiktools-peer</code>, fluxo iroh/QUIC criptografado</td><td>Identidade do par não é autoridade RPC</td></tr><tr><td>WebRTC nativo</td><td><code>tiktools-rtc</code>, sinalização assinada e canais de dados</td><td>Verificações de negociação, concessão e rota continuam necessárias</td></tr></tbody></table><p>A interface de transporte TypeScript fica em <code>src/web/shared/api/control-transport.ts</code>. A configuração de pares nativos não habilita implicitamente relays públicos de terceiros ou descoberta. WebRTC é nativo Rust (<code>webrtc</code> 0.21.1), não uma dependência do <code>RTCPeerConnection</code> do navegador na interface de desktop.</p><h2 id="inspect-the-selected-route" tabindex="-1">Inspecione a rota selecionada <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;Inspecione a rota selecionada {#inspect-the-selected-route}&quot;">​</a></h2><p>Descubra os métodos e capacidades do host conectado antes de parear ou exibir uma ação de controlador:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-browser-transport</span></span></code></pre></div><p><code>tiktools-rtc/src/route.rs</code> observa o par de candidatos ICE selecionado para classificar conexão direta ou via relay. O estado pronto sozinho não comprova uma rota direta. A infraestrutura de sinalização/relay do Cloud é separada da autorização de negócio e deve preservar as verificações nativas de concessão.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>IPC local e transporte de desktop são caminhos estabelecidos. Par nativo, WebRTC e integração do controlador têm código e testes específicos, mas a implantação e a aceitação entre vários PCs continuam experimentais. Textos legados que afirmam não existir implementação de pares/relay são históricos. O IPC local do Android funciona; perfis remotos persistentes não têm armazenamento de credenciais selecionado e addons/WebViews nativos de desktop continuam indisponíveis ali.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Trate a desconexão como possível incerteza para operações aceitas. Reconectar deve invalidar projeções privadas, renegociar a identidade e retomar ou obter instantâneos de fluxos limitados. Nunca reduza verificações de certificado nem retorne silenciosamente a um proprietário local após falha remota. A <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-rtc/src" target="_blank" rel="noreferrer">implementação RTC</a> e o grafo real de recursos substituem planos antigos de transporte.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Peer usa ALPN <code>tiktools/collaboration/1</code>, timeout atual de 15 s e até quatro relays configurados explicitamente. Quadros Peer/RTC têm limite de 1 MiB; RTC fragmenta em pacotes de até 16 KiB. Quadros excessivos falham na validação, sem RPC parcial. Diagnostique configuração/identidade, sinalização, timeout, tamanho e autorização separadamente. Relay Cloud não é servidor TURN ICE; lista vazia não ativa descoberta pública. Confira host/dispositivo e permissão confirmada atual antes da rota; registre se ICE escolheu direto ou relay. Transporte ready/cifrado não prova autoridade nem travessia de todo NAT. Teste sessões alteradas/revogadas e quadros excessivos com fixtures antes de dois PCs reais.</p>`,16)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
